describe('ToolRegistry', () => {
  describe('register', () => {
    it('throws synchronously naming the tool when a static inputSchema fails compilation', () => {
      const registry = new ToolRegistry();

      expect(() =>
        registry.register(
          {
            name: 'broken_tool',
            description: 'Tool with an uncompilable JSON Schema',
            inputSchema: {
              type: 'object',
              properties: {count: {type: 'not-a-type'}},
            },
          },
          async () => 'unreachable'
        )
      ).toThrow(/broken_tool/);
    });
  });

  describe('execute', () => {
    afterEach(() => {
      setLogger(undefined);
    });

    it('rejects a wrong-typed property with a ToolResponse naming the field and expected type without calling the executor or logging the value', async () => {
      const recordedLogs: string[] = [];
      const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
        recordedLogs.push(JSON.stringify({category, message, fields}));
      };
      setLogger({debug: recordLine, info: recordLine, warn: recordLine, error: recordLine});

      const registry = new ToolRegistry();
      let executorCalls = 0;
      registry.register(
        {
          name: 'lookup_user',
          description: 'Look up user by id',
          inputSchema: {
            type: 'object',
            properties: {userId: {type: 'string'}},
            required: ['userId'],
          },
        },
        async () => {
          executorCalls += 1;
          return 'ok';
        }
      );

      const response = await registry.execute('lookup_user', {userId: 987654321});

      expect({
        executorCalls,
        mentionsField: response.result.includes('userId'),
        mentionsExpectedType: response.result.includes('string'),
        leaksValueInResult: response.result.includes('987654321'),
        leaksValueInLogs: recordedLogs.some(line => line.includes('987654321')),
      }).toEqual({
        executorCalls: 0,
        mentionsField: true,
        mentionsExpectedType: true,
        leaksValueInResult: false,
        leaksValueInLogs: false,
      });
    });
  });
});

