function formatValidationErrors(toolName: string, errors: ErrorObject[] | null | undefined): string {
  if (!errors || errors.length === 0) {
    return `Invalid input for tool "${toolName}".`;
  }
  const details = errors.map(formatErrorDetail).join('; ');
  return `Invalid input for tool "${toolName}": ${details}`;
}

function formatErrorDetail(error: ErrorObject): string {
  const trimmedPath = error.instancePath.startsWith('/') ? error.instancePath.slice(1) : error.instancePath;
  const basePath = trimmedPath.replace(/\//g, '.');
  if (error.keyword === 'required') {
    const missing = typeof error.params.missingProperty === 'string' ? error.params.missingProperty : '';
    const fullPath = basePath && missing ? `${basePath}.${missing}` : missing || basePath;
    return `${fullPath || 'input'} is required`;
  }
  const target = basePath || 'input';
  const reason = error.message ?? error.keyword;
  return `${target}: ${reason}`;
}
